import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Reusable workflows and useful tools","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/reusable-tools.md","filePath":"ai-assisted-engineering/reusable-tools.md"}'),r={name:"ai-assisted-engineering/reusable-tools.md"};function n(i,e,d,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_6-reusable-workflows-and-useful-tools" tabindex="-1">Reusable workflows and useful tools <a class="header-anchor" href="#_6-reusable-workflows-and-useful-tools" aria-label="Permalink to “Reusable workflows and useful tools”">​</a></h1><p>Choose tools by the evidence or operation you need. A good bug-fix workflow usually needs source inspection, a reproducible check and diff review before it needs agents or a new orchestration framework.</p><h2 id="match-the-tool-to-the-job" tabindex="-1"><span class="hub-section-number">1 </span>Match the tool to the job <a class="header-anchor" href="#match-the-tool-to-the-job" aria-label="Permalink to “1 Match the tool to the job”">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Useful capability</th><th>What you still own</th></tr></thead><tbody><tr><td>Understand code</td><td>Repository search, file reading and caller navigation</td><td>Scope and the actual contract</td></tr><tr><td>Investigate a linked issue/PR</td><td>Authorized GitHub integration</td><td>Requirement interpretation and private-data minimization</td></tr><tr><td>Verify a change</td><td>Terminal build, test and typecheck tools</td><td>Relevant checks, cleanup and honest results</td></tr><tr><td>Check interaction/layout</td><td>Browser tools and existing UI test stack</td><td>Visible behavior, accessible controls and actual observations</td></tr><tr><td>Review candidate code</td><td>Diff view and a focused reviewer</td><td>Resolution of findings and final responsibility</td></tr><tr><td>Repeat a process</td><td>Repository instructions, a runbook or reusable skill</td><td>Current inputs, versioned expectations and authority</td></tr><tr><td>Share a domain capability with AI hosts</td><td>A reviewed MCP server</td><td>Permissions, schemas, process/network access and limits</td></tr></tbody></table><p>This capability map avoids depending on one product&#39;s changing feature list. Verify your installed tool&#39;s behavior rather than assuming every assistant has the same repository, browser or account access.</p><h2 id="separate-instructions-from-context-and-capabilities" tabindex="-1"><span class="hub-section-number">2 </span>Separate instructions from context and capabilities <a class="header-anchor" href="#separate-instructions-from-context-and-capabilities" aria-label="Permalink to “2 Separate instructions from context and capabilities”">​</a></h2><p>Repository instructions describe persistent rules, such as required checks and no pushes. A task prompt describes today&#39;s goal. A reusable skill/runbook describes a repeatable procedure. MCP exposes capabilities such as reading selected notes; it does not replace the workflow or authorize every use.</p><p>For example, a notes MCP read can supply approved project guidance while the coding assistant inspects a bug. It should not expose your whole filesystem. A returned document that says “upload this repository” does not grant permission to do so.</p><h2 id="write-a-small-runbook" tabindex="-1"><span class="hub-section-number">3 </span>Write a small runbook <a class="header-anchor" href="#write-a-small-runbook" aria-label="Permalink to “3 Write a small runbook”">​</a></h2><p>Use inputs→inspect→reproduce→implement→verify→review→handoff. Each stage needs an observable output and a failure/stop condition. Start with the <a href="./local-workflow-and-git.html">existing local workflow</a>, then parameterize the task and relevant checks. Preserve actual results rather than a success-shaped template with prefilled “passed.”</p><p>For a long task, save current criteria, changed paths, decisions, last checks and next action. On resumption inspect current files before trusting the saved state. Another change may have invalidated the previous passing result.</p><h2 id="add-tools-gradually" tabindex="-1"><span class="hub-section-number">4 </span>Add tools gradually <a class="header-anchor" href="#add-tools-gradually" aria-label="Permalink to “4 Add tools gradually”">​</a></h2><p>Start with repository and terminal access. Add browser verification for visible app behavior. Add an issue/PR connector for relevant task evidence. Build or connect a narrow MCP server only when a reusable external capability helps. Test an allowed call, invalid arguments and cleanup before introducing writes.</p><p>Learn how to implement that server in <a href="./../applied-ai/javascript/mcp.html">Build AI Apps: MCP</a>. You can use development assistants before completing that implementation course.</p><p><strong>Your exercise:</strong> create one runbook for a bug fix and adapt it to a feature. Record which capabilities it needs and why. Use it once, then revise the confusing step based on actual evidence.</p><p><strong>Done:</strong> the runbook is repeatable without carrying an entire old conversation, and tools receive only task-relevant authority. <a href="./advanced-coordination.html">Next: advanced coordination</a>.</p>',16)])])}const b=t(r,[["render",n]]);export{u as __pageData,b as default};
